cd /work; mkdir postgres; cat > postgres/schema.sql <<'E'
CREATE TABLE customers (
    customer_id   bigint PRIMARY KEY,
    customer_name varchar(120) NOT NULL,
    status        varchar(20) DEFAULT 'ACTIVE'
);
CREATE TABLE orders (
    order_id    bigint PRIMARY KEY,
    customer_id bigint NOT NULL,
    order_total numeric(12,2) NOT NULL,
    order_date  timestamptz NOT NULL
);
CREATE TABLE customer_tiers (
    customer_id   bigint PRIMARY KEY,
    customer_name varchar(120),
    total_spend   numeric(12,2),
    order_count   numeric,
    tier          varchar(20),
    computed_at   timestamptz
);
CREATE SEQUENCE seq_tier_id START WITH 1 INCREMENT BY 1;
CREATE TABLE products (
    product_id   bigint PRIMARY KEY,
    product_name varchar(120),
    category     varchar(60)
);
CREATE TABLE order_items (
    order_item_id bigint PRIMARY KEY,
    order_id      bigint,
    product_id    bigint,
    quantity      numeric,
    unit_price    numeric(10,2)
);
CREATE TABLE monthly_report (
    report_month varchar(7),
    category     varchar(60),
    revenue      numeric(12,2),
    units_sold   numeric
);
E
cat > postgres/procedures.sql <<'E'
CREATE OR REPLACE PROCEDURE sp_customer_tier()
LANGUAGE plpgsql AS $$
DECLARE
    v_tier   varchar(20);
    rec      record;
BEGIN
    DELETE FROM customer_tiers;
    FOR rec IN
        SELECT o.customer_id, c.customer_name,
               SUM(o.order_total) AS total_spend,
               COUNT(*)           AS order_count
        FROM   orders o
        JOIN   customers c ON c.customer_id = o.customer_id
        WHERE  COALESCE(c.status, 'ACTIVE') = 'ACTIVE'
        GROUP  BY o.customer_id, c.customer_name
        ORDER  BY 3, 1
    LOOP
        IF rec.total_spend >= 1000 THEN v_tier := 'GOLD';
        ELSIF rec.total_spend >= 500 THEN v_tier := 'SILVER';
        ELSE v_tier := 'BRONZE';
        END IF;
        INSERT INTO customer_tiers
            (customer_id, customer_name, total_spend, order_count, tier, computed_at)
        VALUES (rec.customer_id, rec.customer_name, rec.total_spend,
                rec.order_count, v_tier, now());
    END LOOP;
END;
$$;

CREATE OR REPLACE PROCEDURE sp_monthly_report(p_month varchar)
LANGUAGE plpgsql AS $$
DECLARE
    rec        record;
    v_has_data integer := 1;  -- Oracle: SELECT COUNT(*) FROM DUAL (always 1)
BEGIN
    DELETE FROM monthly_report WHERE report_month = p_month;
    FOR rec IN
        SELECT p.category AS category,
               COALESCE(SUM(oi.quantity * oi.unit_price), 0) AS revenue,
               COALESCE(SUM(oi.quantity), 0) AS units_sold
        FROM   order_items oi
        JOIN   products p ON p.product_id = oi.product_id
        GROUP  BY p.category
        ORDER  BY 2 DESC
    LOOP
        INSERT INTO monthly_report (report_month, category, revenue, units_sold)
        VALUES (p_month, rec.category, rec.revenue, rec.units_sold);
    END LOOP;
    IF v_has_data = 0 THEN
        RAISE EXCEPTION 'no data' USING ERRCODE = 'P0002';
    END IF;
EXCEPTION
    WHEN no_data_found THEN
        NULL;  -- Oracle handler swallowed e_no_data (rollback is implicit on subtransaction)
END;
$$;
E
psql -q -v ON_ERROR_STOP=1 -f postgres/schema.sql -f postgres/procedures.sql -f seed.sql && psql -c "call sp_customer_tier()" -c "call sp_monthly_report('2026-09')" -c "select customer_id,customer_name,total_spend,order_count,tier from customer_tiers" -c "select report_month,category,revenue,units_sold from monthly_report"

